    async def batch(
        self,
        *calls: Call[Any],
        timeout: float | None = None,
        max_retries: int | None = None,
        correlation_id: str | None = None,
        extra_headers: Mapping[str, str] | None = None,
    ) -> tuple[BatchResult[Any], ...]:
        """Several operations of the FHIR base in one request, each with its own answer or error, in the order given.

        Each entry comes from `haau3.calls`, called as the method of the same name is. A result is a
        `BatchOk` (`data`, `status`) or a `BatchError` (`error`, the `RefusedError` or `NoAnswerError`
        the call alone would have raised), typed by position for up to six entries:

        ```python
        from haau3 import BatchOk, calls

        plan, counties = await client.batch(
            calls.read_insurance_plan("H2406-013-000"),
            calls.list_insurance_plan_counties(state="NC"),
        )
        if isinstance(plan, BatchOk):
            print(plan.data["name"])
        ```

        Each entry is checked as the call alone is, and fails alone. An entry that fails is not
        retried; the batch itself is retried, and raises, as any call does. The API takes up to 100
        entries in up to 1 MiB and gives a batch 60 seconds. `process_message` and `reconcile_medications` cannot go in a batch.
        """
        return (await self._engine.batch(calls, Options(timeout, max_retries, correlation_id, extra_headers))).data


